import pytest
from pytest_given import given, scenario

@scenario('Pinning')
@pytest.mark.parametrize('pinned', [False, True])
def test_pin(pinned):
    with given(t'a step that {pinned:pins it|does not pin it}'):
        assert pinned in (False, True)

